  virtual,
  count,
}: {
  table: Table<T>
  labels: DataTableLabels
  virtual: boolean
  count: number
}) {
  "use no memo"
  // Table v8 的对象引用稳定，子组件同样需要读取当前状态。
  const { pageIndex, pageSize } = table.getState().pagination
  const pages = Math.max(1, table.getPageCount())
  return (
    <div
      data-slot="data-table-pagination"
      className="flex flex-wrap items-center justify-between gap-3 border-t border-edge p-4 text-sm tabular-nums"
    >
      <span className="font-mono text-xs text-muted-foreground">
        {String(count ? pageIndex * pageSize + 1 : 0).padStart(2, "0")}–
        {String(
          virtual ? count : Math.min(count, (pageIndex + 1) * pageSize),
        ).padStart(2, "0")}{" "}
        / {count}
      </span>
      {!virtual && (
        <>
          <label className="hidden items-center gap-2 @min-[40rem]:flex">
            {labels.perPage}
            <select
              className="h-8 rounded-md border border-edge bg-background px-2 pointer-coarse:h-10"
              value={pageSize}
              onChange={(event) =>
                table.setPageSize(Number(event.target.value))
              }
            >
              {[10, 20, 50, 100].map((size) => (
                <option key={size}>{size}</option>
              ))}
            </select>
          </label>
          <div className="flex items-center gap-2">
